.publicvaluesim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #1d2b24;
    background: linear-gradient(160deg, #f3f6f1 0%, #eaf1ea 100%);
    border-radius: 18px;
}

.publicvaluesim-container * {
    box-sizing: border-box;
}

.publicvaluesim-header {
    text-align: center;
    padding: 26px 20px 22px;
    background: linear-gradient(135deg, #0f3d2e 0%, #145138 55%, #1c7a4f 100%);
    color: #f4faf5;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(15, 61, 46, 0.30);
    border-bottom: 4px solid #d6a52a;
}

.publicvaluesim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.3rem;
    font-weight: 800;
    letter-spacing: -0.5px;
}

.publicvaluesim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #f0dca0;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.publicvaluesim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.55;
    color: #dcefe1;
}

.publicvaluesim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #1a4f38;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.publicvaluesim-period-counter #currentDay,
.publicvaluesim-period-counter #maxPeriods {
    font-weight: 800;
    color: #0f3d2e;
}

.publicvaluesim-round-name {
    background: #d8ecdd;
    color: #0f3d2e;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.publicvaluesim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #9a4a12;
    background: #fbeda9;
    padding: 4px 12px;
    border-radius: 999px;
}

.publicvaluesim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.publicvaluesim-status-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #d9e6dc;
    box-shadow: 0 4px 14px rgba(15, 61, 46, 0.06);
    border-top: 4px solid #1c7a4f;
}

.publicvaluesim-card-value { border-top-color: #0f7a4f; }
.publicvaluesim-card-quality { border-top-color: #2f7fb0; }
.publicvaluesim-card-account { border-top-color: #6a4fb0; }
.publicvaluesim-card-clock { border-top-color: #d6a52a; }

.publicvaluesim-label {
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #5b7064;
}

.publicvaluesim-value {
    font-size: 2.5rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #0f3d2e;
}

.publicvaluesim-card-value .publicvaluesim-value { color: #0f7a4f; }
.publicvaluesim-card-quality .publicvaluesim-value { color: #2f7fb0; }
.publicvaluesim-card-account .publicvaluesim-value { color: #6a4fb0; }
.publicvaluesim-card-clock .publicvaluesim-value { color: #b3851a; }

.publicvaluesim-sublabel {
    font-size: 0.76rem;
    color: #6f867a;
    line-height: 1.35;
}

.publicvaluesim-value-fail .publicvaluesim-value { color: #c0392b; }
.publicvaluesim-value-target .publicvaluesim-value { color: #0f7a4f; }

.publicvaluesim-clock-over { border-top-color: #c0392b; }
.publicvaluesim-clock-over .publicvaluesim-value { color: #c0392b; }

.publicvaluesim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #0f3d2e;
    color: #eaf6ee;
    padding: 10px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
    border-left: 5px solid #d6a52a;
}

.publicvaluesim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.publicvaluesim-briefing {
    display: flex;
    gap: 14px;
    background: #ffffff;
    border-left: 5px solid #1c7a4f;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(15, 61, 46, 0.05);
}

.publicvaluesim-briefing-icon {
    font-size: 1.8rem;
    line-height: 1;
}

.publicvaluesim-briefing-title {
    font-weight: 800;
    font-size: 1.08rem;
    color: #0f3d2e;
    margin-bottom: 6px;
}

.publicvaluesim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.55;
    color: #2b4036;
}

.publicvaluesim-briefing-text strong { color: #0f7a4f; }
.publicvaluesim-briefing-text em { color: #9a4a12; font-style: italic; }

.publicvaluesim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #d9e6dc;
    box-shadow: 0 4px 14px rgba(15, 61, 46, 0.06);
}

.publicvaluesim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #0f3d2e;
    border-bottom: 2px solid #e6efe7;
    padding-bottom: 8px;
}

.publicvaluesim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #20402f;
    margin: 14px 0 6px;
}

.publicvaluesim-container select,
.publicvaluesim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #bcd6c4;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #f7fbf8;
    color: #1d2b24;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.publicvaluesim-container select:focus,
.publicvaluesim-container input[type="number"]:focus {
    outline: none;
    border-color: #1c7a4f;
    box-shadow: 0 0 0 3px rgba(28, 122, 79, 0.15);
}

.publicvaluesim-container select option {
    background-color: #ffffff;
    color: #1d2b24;
}

.publicvaluesim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #1c7a4f;
}

.publicvaluesim-range-readout,
.publicvaluesim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #14633f;
    margin-top: 4px;
}

.publicvaluesim-range-readout span:nth-child(2),
.publicvaluesim-alloc-readout span:nth-child(2) {
    color: #0f7a4f;
    font-weight: 800;
}

.publicvaluesim-hint {
    font-size: 0.8rem;
    color: #6f867a;
    margin-top: 4px;
    line-height: 1.4;
}

.publicvaluesim-alloc-grid {
    display: flex;
    flex-direction: column;
    gap: 8px;
    margin-top: 4px;
}

.publicvaluesim-alloc-row {
    display: flex;
    align-items: center;
    gap: 12px;
    background: #f2f9f4;
    border: 1px solid #dcebe0;
    border-radius: 9px;
    padding: 8px 12px;
}

.publicvaluesim-alloc-name {
    flex: 1;
    font-size: 0.88rem;
    font-weight: 600;
    color: #20402f;
}

.publicvaluesim-alloc-row input[type="number"] {
    width: 90px;
    flex: 0 0 90px;
}

.publicvaluesim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.publicvaluesim-container .btn-primary {
    background: linear-gradient(135deg, #0f7a4f 0%, #1c7a4f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(15, 122, 79, 0.28);
}

.publicvaluesim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.publicvaluesim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #bcd6c4;
    color: #5b7064;
}

.publicvaluesim-coach {
    background: #0f3d2e;
    color: #eaf6ee;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(15, 61, 46, 0.22);
    border-left: 5px solid #d6a52a;
}

.publicvaluesim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #8fd1ad;
    margin-bottom: 8px;
}

.publicvaluesim-coach-body {
    font-size: 0.95rem;
    line-height: 1.55;
}

.publicvaluesim-coach-body strong { color: #f0dca0; }
.publicvaluesim-coach-body em { color: #f3c9a0; font-style: italic; }

.publicvaluesim-history,
.publicvaluesim-chart {
    background: #ffffff;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #d9e6dc;
    box-shadow: 0 4px 14px rgba(15, 61, 46, 0.06);
}

.publicvaluesim-history h3,
.publicvaluesim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #0f3d2e;
}

.publicvaluesim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #20402f;
}

.publicvaluesim-container table#usfHistoryTable th {
    background: #eaf3ec;
    color: #0f3d2e;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #d4e6d9;
}

.publicvaluesim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #eef4f0;
}

.publicvaluesim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #f7fbf8;
}

.publicvaluesim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .publicvaluesim-container {
        padding: 14px;
    }
    .publicvaluesim-header h1 {
        font-size: 1.7rem;
    }
    .publicvaluesim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .publicvaluesim-value {
        font-size: 2rem;
    }
    .publicvaluesim-clock {
        margin-left: 0;
    }
    .publicvaluesim-period-counter {
        font-size: 0.88rem;
    }
    .publicvaluesim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .publicvaluesim-alloc-row {
        flex-wrap: wrap;
    }
    .publicvaluesim-alloc-row input[type="number"] {
        width: 100%;
        flex: 1 1 100%;
    }
    .publicvaluesim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ===== v1.1.0 completion modal (append-only, dark-on-light) ===== */
.publicvaluesim-completion { color:#22332a; font-size:0.95rem; }
.publicvaluesim-cm-head { text-align:center; margin-bottom:16px; }
.publicvaluesim-cm-score { font-size:3.2rem; font-weight:800; line-height:1; color:#2c6e57; }
.publicvaluesim-cm-score-max { font-size:1.2rem; font-weight:600; color:#6aa78f; }
.publicvaluesim-cm-grade { font-size:1.2rem; font-weight:700; margin-top:6px; color:#153226; }
.publicvaluesim-cm-badge { display:inline-block; margin-left:6px; padding:2px 10px; border-radius:999px; font-size:0.78rem; font-weight:700; vertical-align:middle; }
.publicvaluesim-cm-yes { background:rgba(44,110,87,0.14); color:#245b48; border:1px solid rgba(44,110,87,0.5); }
.publicvaluesim-cm-no { background:rgba(201,138,22,0.16); color:#8a6a1f; border:1px solid rgba(201,138,22,0.5); }
.publicvaluesim-cm-fail { background:rgba(192,57,43,0.12); color:#b0392b; border:1px solid rgba(192,57,43,0.45); }
.publicvaluesim-cm-metrics { display:flex; flex-wrap:wrap; gap:10px; justify-content:center; margin:12px 0 16px; }
.publicvaluesim-cm-metric { flex:1 1 110px; min-width:100px; background:rgba(21,50,38,0.06); border:1px solid rgba(21,50,38,0.16); border-radius:10px; padding:10px 8px; text-align:center; }
.publicvaluesim-cm-mv { display:block; font-size:1.4rem; font-weight:800; color:#1f3a2c; }
.publicvaluesim-cm-ml { display:block; font-size:0.72rem; margin-top:4px; color:#5b7064; text-transform:uppercase; letter-spacing:0.03em; }
.publicvaluesim-cm-insights-title { font-weight:700; margin:8px 0 6px; color:#153226; }
.publicvaluesim-cm-insights { margin:0; padding-left:20px; }
.publicvaluesim-cm-insights li { margin:4px 0; color:#2d4638; }

