(function() {
    'use strict';

    class PublicValueAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Public Value`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Brazil / BRL).
            this.TARGET_VALUE = 70;       // composite Public Value win target (reachable)
            this.QUALITY_FLOOR = 98;      // clinical on-time requirement (proxy ≥80 in-sim)
            this.AWARD_DEADLINE = 49;     // award & mobilise by day 49
            this.SURGE_DAY = 63;          // hard clinical deadline
            this.BUDGET_CAP = 28.0;       // life-cycle cost ceiling, R$ millions
            this.INCENTIVE_BAND = 8;      // ±8% of contract value (≈ R$1.76M)
            this.TELEMETRY_COST = 0.24;   // ~R$240k / year, in R$ millions

            // Concept-correct truths.
            this.TRUE_ROOT = `design`;
            this.TRUE_INSTRUMENT = `tecnicaepreco`;
            this.TRUE_VENDOR = `balanced`;
            this.TRUE_SLA = `measurable`;
            this.TRUE_EXIT = `triggered`;
            this.TRUE_OVERSIGHT = `hybrid`;
            this.TRUE_SHOCK = `evidence`;
            this.TRUE_DEFENCE = `value`;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    valuePV: 6,
                    quality: 20,
                    account: 15,
                    clockUsed: 0,
                    budgetUsed: 0,
                    contractValue: 22.0,   // R$ millions, set in round 2 by vendor choice
                    surgeBreached: false,
                    dispensaUsed: false,
                    targetMissed: false,
                    valueHistory: [6],
                    qualityHistory: [20],
                    accountHistory: [15],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seeded defaults are a deliberately MIDDLING / neutral mix — not the textbook play.
                state.decisions = {
                    root: `vendor`,
                    instrument: `pregao`,
                    frame: 50,
                    priceWeight: 50,
                    qualityWeight: 50,
                    vendor: `cheap`,
                    threshold: 90,
                    sla: `reasonable`,
                    penalty: 2,
                    bonus: 2,
                    exit: `discretion`,
                    oversight: `inhouse`,
                    shock: `ignore`,
                    defence: `cheapest`,
                    conviction: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const root = document.getElementById(`rootInput`);
                const inst = document.getElementById(`instrumentInput`);
                const fr = document.getElementById(`frameInput`);
                if (root) decisions.root = root.value;
                if (inst) decisions.instrument = inst.value;
                if (fr) decisions.frame = parseInt(fr.value, 10);
                if (!Number.isFinite(decisions.frame) || decisions.frame < 0 || decisions.frame > 100) {
                    warn(`warn_frame_range`); return false;
                }
            } else if (round === 2) {
                const pw = document.getElementById(`priceWeightInput`);
                const qw = document.getElementById(`qualityWeightInput`);
                const ve = document.getElementById(`vendorInput`);
                const th = document.getElementById(`thresholdInput`);
                if (pw) decisions.priceWeight = parseInt(pw.value, 10);
                if (qw) decisions.qualityWeight = parseInt(qw.value, 10);
                if (ve) decisions.vendor = ve.value;
                if (th) decisions.threshold = parseInt(th.value, 10);
                if (!Number.isFinite(decisions.priceWeight) || !Number.isFinite(decisions.qualityWeight) ||
                    decisions.priceWeight < 0 || decisions.qualityWeight < 0) {
                    warn(`warn_weight_negative`); return false;
                }
                if ((decisions.priceWeight + decisions.qualityWeight) !== 100) {
                    warn(`warn_weight_total`); return false;
                }
                if (!Number.isFinite(decisions.threshold) || decisions.threshold < 80 || decisions.threshold > 99) {
                    warn(`warn_threshold_range`); return false;
                }
            } else if (round === 3) {
                const sl = document.getElementById(`slaInput`);
                const pe = document.getElementById(`penaltyInput`);
                const bo = document.getElementById(`bonusInput`);
                const ex = document.getElementById(`exitInput`);
                if (sl) decisions.sla = sl.value;
                if (pe) decisions.penalty = parseInt(pe.value, 10);
                if (bo) decisions.bonus = parseInt(bo.value, 10);
                if (ex) decisions.exit = ex.value;
                if (!Number.isFinite(decisions.penalty) || decisions.penalty < 0 || decisions.penalty > this.INCENTIVE_BAND) {
                    warn(`warn_penalty_band`); return false;
                }
                if (!Number.isFinite(decisions.bonus) || decisions.bonus < 0 || decisions.bonus > this.INCENTIVE_BAND) {
                    warn(`warn_bonus_band`); return false;
                }
            } else if (round === 4) {
                const ov = document.getElementById(`oversightInput`);
                const sh = document.getElementById(`shockInput`);
                const de = document.getElementById(`defenceInput`);
                const cv = document.getElementById(`convictionInput`);
                if (ov) decisions.oversight = ov.value;
                if (sh) decisions.shock = sh.value;
                if (de) decisions.defence = de.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas: value = public value composite driver; quality = service delivery proxy;
            // account = audit-defensibility; clock = days consumed toward day-49 award; spend = life-cycle R$M.
            let valueDelta = 0, qualityDelta = 0, accountDelta = 0;
            let clockDelta = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the design failure, not bad luck / underpricing / careless staff (Common Error 1).
                if (d.root === this.TRUE_ROOT) {
                    valueDelta += 10; accountDelta += 8; coachKey = `coach_r1_root_right`;
                } else if (d.root === `vendor`) {
                    valueDelta -= 6; accountDelta -= 4; coachKey = `coach_r1_root_vendor`;
                } else if (d.root === `price`) {
                    valueDelta -= 4; accountDelta -= 2; coachKey = `coach_r1_root_price`;
                } else {
                    valueDelta -= 8; accountDelta -= 4; coachKey = `coach_r1_root_staff`;
                }

                // Instrument choice vs the 63-day clock (instrument = a value lever, not a formality).
                switch (d.instrument) {
                    case `tecnicaepreco`:
                        valueDelta += 12; accountDelta += 8; clockDelta += 40;
                        if (d.root === this.TRUE_ROOT) coachKey = `coach_r1_instrument_sharp`;
                        break;
                    case `pregao`:
                        // Too slow AND lowest-price-only: blows the clock and primes the failure mode.
                        valueDelta -= 6; qualityDelta -= 4; clockDelta += 78; coachKey = `coach_r1_pregao`;
                        break;
                    case `dialogo`:
                        // Rich but far too slow for a 63-day clock.
                        valueDelta -= 4; clockDelta += 95; coachKey = `coach_r1_dialogo`;
                        break;
                    case `dispensa`:
                        // Legal, fast, but a reform-failure banner: gutted accountability and value.
                        valueDelta -= 14; accountDelta -= 18; clockDelta += 20;
                        ds.dispensaUsed = true; coachKey = `coach_r1_dispensa`;
                        break;
                }

                // Clarity of the decision frame → accountability.
                if (d.frame >= 60) { accountDelta += 6; valueDelta += 2; }
                else if (d.frame <= 25) { accountDelta -= 6; coachKey = `coach_r1_vagueframe`; }

                summaryKey = (d.root === this.TRUE_ROOT && d.instrument === this.TRUE_INSTRUMENT) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Published best-value evaluation + vendor choice (Common Errors 1 & 2).
                const qW = d.qualityWeight;

                // Weighting: a quality-leaning but balanced model is best value; price-heavy = lowest-price reflex.
                if (qW >= 40 && qW <= 65) {
                    valueDelta += 8; accountDelta += 8; coachKey = `coach_r2_weight_balanced`;
                } else if (qW < 25) {
                    valueDelta -= 8; qualityDelta -= 4; accountDelta -= 2; coachKey = `coach_r2_weight_priceheavy`;
                } else if (qW > 80) {
                    // Quality-only with no price discipline is also indefensible to the TCE.
                    valueDelta -= 2; accountDelta -= 4; coachKey = `coach_r2_weight_qualityonly`;
                } else {
                    valueDelta += 3; accountDelta += 3;
                }

                // Vendor choice. Mid bid = best value. Cheap = lowest-price trap. Premium = de-risks but costly.
                switch (d.vendor) {
                    case `balanced`:
                        ds.contractValue = 21.2;
                        valueDelta += 12; qualityDelta += 18; coachKey = `coach_r2_vendor_balanced`;
                        break;
                    case `cheap`:
                        ds.contractValue = 18.6;
                        // Cheapest headline, but ~84% track record endangers patients and primes a re-default.
                        valueDelta -= 10; qualityDelta -= 6; accountDelta -= 4; coachKey = `coach_r2_vendor_cheap`;
                        break;
                    case `premium`:
                        ds.contractValue = 24.3;
                        // De-risks the surge but only defensible if the published weighting actually justifies the spend.
                        qualityDelta += 16;
                        if (qW >= 40) { valueDelta += 4; accountDelta += 2; coachKey = `coach_r2_vendor_premium_ok`; }
                        else { valueDelta -= 4; accountDelta -= 4; coachKey = `coach_r2_vendor_premium_unjust`; }
                        break;
                }

                // Published minimum on-time threshold → quality + accountability (each point toward 98 matters).
                if (d.threshold >= 97) { qualityDelta += 8; accountDelta += 6; }
                else if (d.threshold >= 93) { qualityDelta += 4; accountDelta += 3; }
                else { qualityDelta -= 4; accountDelta -= 2; coachKey = `coach_r2_lowthreshold`; }

                // Booking the contract value into life-cycle cost.
                spend += ds.contractValue;

                summaryKey = (d.vendor === this.TRUE_VENDOR && qW >= 40 && qW <= 65) ? `sum_r2_good` :
                             (d.vendor === `cheap` ? `sum_r2_trap` : `sum_r2_weak`);
            } else if (round === 3) {
                // Calibrate enforceable, balanced incentives in the ±8% band (Common Errors 3 & 4).
                // SLA wording: must be exact and measurable to be enforceable.
                switch (d.sla) {
                    case `measurable`: valueDelta += 8; qualityDelta += 8; accountDelta += 8; coachKey = `coach_r3_sla_measurable`; break;
                    case `reasonable`: valueDelta -= 8; qualityDelta -= 4; accountDelta -= 6; coachKey = `coach_r3_sla_reasonable`; break;
                    case `annual`: valueDelta -= 4; qualityDelta -= 2; accountDelta -= 2; coachKey = `coach_r3_sla_annual`; break;
                }

                // Penalty/bonus calibration. A measurable bonus that rewards AND a moderate penalty that bites
                // is the calibration point; max penalty with no bonus invites padding, gaming and bidder flight.
                const balanced = d.penalty >= 3 && d.penalty <= 6 && d.bonus >= 2 && d.bonus <= 6;
                const toothless = d.penalty <= 1 && d.bonus <= 1;
                const overload = d.penalty >= 7 && d.bonus <= 1;
                if (balanced) {
                    valueDelta += 9; qualityDelta += 8; coachKey = `coach_r3_calibrated`;
                } else if (overload) {
                    // Penalty overload: vendor pads price (life-cycle cost rises), games the metric, good bidders flee.
                    valueDelta -= 10; qualityDelta -= 6; accountDelta -= 4; spend += 1.2; coachKey = `coach_r3_overload`;
                } else if (toothless) {
                    // Incentives so weak they do not move behaviour.
                    valueDelta -= 8; qualityDelta -= 4; coachKey = `coach_r3_toothless`;
                } else if (d.bonus === 0 && d.penalty >= 4) {
                    valueDelta -= 4; qualityDelta -= 2; coachKey = `coach_r3_nobonus`;
                } else {
                    valueDelta += 4; qualityDelta += 2;
                }

                // Exit / termination trigger so the city is never trapped again.
                switch (d.exit) {
                    case `triggered`: valueDelta += 6; accountDelta += 8; qualityDelta += 2; break;
                    case `discretion`: accountDelta -= 2; coachKey = (d.sla === `measurable` ? coachKey : `coach_r3_discretion`); break;
                    case `none`: valueDelta -= 6; accountDelta -= 8; coachKey = `coach_r3_noexit`; break;
                }

                summaryKey = (d.sla === `measurable` && balanced && d.exit === `triggered`) ? `sum_r3_good` :
                             (overload ? `sum_r3_overload` : (toothless || d.sla !== `measurable` ? `sum_r3_weak` : `sum_r3_partial`));
            } else if (round === 4) {
                // Oversight, the shock, and the TCE defence (Common Error 5 + reform-failure trap).
                switch (d.oversight) {
                    case `hybrid`:
                        spend += this.TELEMETRY_COST;
                        valueDelta += 8; qualityDelta += 8; accountDelta += 12; coachKey = `coach_r4_hybrid`;
                        break;
                    case `inhouse`:
                        // Cheap on paper, but how the last contract eroded unseen; a default costs ~R$140k/week.
                        valueDelta -= 8; qualityDelta -= 8; accountDelta -= 6; coachKey = `coach_r4_inhouse`;
                        break;
                    case `telemetry`:
                        spend += this.TELEMETRY_COST;
                        // Data with nobody acting on it: catches dips but no human governance or audit credibility.
                        valueDelta += 2; qualityDelta += 4; accountDelta -= 2; coachKey = `coach_r4_telemetryonly`;
                        break;
                    case `thirdparty`:
                        spend += 0.18;
                        // Independent credibility but no live data: finds problems late, after the surge.
                        valueDelta += 2; accountDelta += 6; qualityDelta -= 2; coachKey = `coach_r4_thirdpartyonly`;
                        break;
                }

                // The shock: a delivery dip + a bidder challenge. Evidence-led response is the point of oversight.
                switch (d.shock) {
                    case `evidence`:
                        valueDelta += 6; qualityDelta += 6; accountDelta += 10;
                        if (d.oversight === this.TRUE_OVERSIGHT) coachKey = `coach_r4_shock_evidence`;
                        break;
                    case `ignore`:
                        valueDelta -= 8; qualityDelta -= 8; accountDelta -= 6; coachKey = `coach_r4_shock_ignore`;
                        break;
                    case `dispensa`:
                        valueDelta -= 14; accountDelta -= 16; ds.dispensaUsed = true; coachKey = `coach_r4_shock_dispensa`;
                        break;
                }

                // Closing case to the mock TCE / Controladoria panel.
                switch (d.defence) {
                    case `value`:
                        valueDelta += 8; accountDelta += 10;
                        if (d.shock === this.TRUE_SHOCK) coachKey = `coach_r4_def_value`;
                        break;
                    case `cheapest`:
                        valueDelta -= 6; accountDelta -= 4; coachKey = `coach_r4_def_cheapest`;
                        break;
                    case `trust`:
                        // 'It's better' without a reproducible model is how officers end up explaining to the TCE.
                        accountDelta -= 12; valueDelta -= 4; coachKey = `coach_r4_def_trust`;
                        break;
                }

                // Conviction that agility + accountability are complementary nudges value.
                valueDelta += Math.round((d.conviction - 55) / 9);

                summaryKey = (d.oversight === this.TRUE_OVERSIGHT && d.shock === this.TRUE_SHOCK && d.defence === this.TRUE_DEFENCE) ? `sum_r4_good` : `sum_r4_weak`;
            }

            // Clock accounting (days toward the day-49 award & mobilise deadline).
            ds.clockUsed = Math.max(0, ds.clockUsed + clockDelta);
            if (ds.clockUsed > this.SURGE_DAY) ds.surgeBreached = true;

            // A blown clock past day 49 hurts value (delay → ~R$140k/week surge cost); past 63 is a hard failure.
            if (round === 1) {
                if (ds.clockUsed > this.SURGE_DAY) {
                    valueDelta -= 18; qualityDelta -= 8; accountDelta -= 6;
                    coachKey = `coach_r1_surgemiss`;
                } else if (ds.clockUsed > this.AWARD_DEADLINE) {
                    valueDelta -= 8; coachKey = (d.instrument === this.TRUE_INSTRUMENT ? coachKey : `coach_r1_slowclock`);
                }
            }

            // Resource accounting.
            ds.budgetUsed = Math.round((ds.budgetUsed + spend) * 100) / 100;

            // KPIs move on their deltas (clamped 0–100, low start leaves headroom into the final round).
            ds.valuePV = Math.max(0, Math.min(100, ds.valuePV + valueDelta));
            ds.quality = Math.max(0, Math.min(100, ds.quality + qualityDelta));
            ds.account = Math.max(0, Math.min(100, ds.account + accountDelta));

            ds.valueHistory.push(Math.round(ds.valuePV));
            ds.qualityHistory.push(Math.round(ds.quality));
            ds.accountHistory.push(Math.round(ds.account));
            ds.performance = { overallScore: this._composite(ds) };

            if (round === this.ROUNDS.length && ds.valuePV < this.TARGET_VALUE) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            return {
                period: state.currentPeriod,
                valuePV: Math.round(ds.valuePV),
                valueDelta: Math.round(valueDelta),
                quality: Math.round(ds.quality),
                qualityDelta: Math.round(qualityDelta),
                account: Math.round(ds.account),
                accountDelta: Math.round(accountDelta),
                clockUsed: ds.clockUsed,
                budgetUsed: ds.budgetUsed,
                surgeBreached: ds.surgeBreached,
                dispensaUsed: ds.dispensaUsed,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`valueDisplay`, `domainState.valuePV`, (v) => {
                const card = document.querySelector(`.publicvaluesim-card-value`);
                if (card) {
                    card.classList.toggle(`publicvaluesim-value-target`, Number(v) >= this.TARGET_VALUE);
                    card.classList.toggle(`publicvaluesim-value-fail`, Number(v) < this.TARGET_VALUE);
                }
                return Math.round(Number(v));
            });
            uiManager.bind(`qualityDisplay`, `domainState.quality`, (v) => Math.round(Number(v)));
            uiManager.bind(`accountDisplay`, `domainState.account`, (v) => Math.round(Number(v)));
            uiManager.bind(`clockUsedDisplay`, `domainState.clockUsed`, (v) => {
                const card = document.querySelector(`.publicvaluesim-card-clock`);
                if (card) card.classList.toggle(`publicvaluesim-clock-over`, Number(v) > this.AWARD_DEADLINE);
                return Math.round(Number(v)) + ` / 49`;
            });
            uiManager.bind(`budgetDisplay`, `domainState.budgetUsed`, (v) => this._brl(Number(v)) + ` / R$28,0M`);

            const self = this;

            // Frame slider readout.
            const fr = document.getElementById(`frameInput`);
            const frReadout = document.getElementById(`frameReadout`);
            if (fr && frReadout) {
                frReadout.textContent = fr.value;
                fr.addEventListener(`input`, function() { frReadout.textContent = fr.value; });
            }

            // Penalty slider readout.
            const pe = document.getElementById(`penaltyInput`);
            const peReadout = document.getElementById(`penaltyReadout`);
            if (pe && peReadout) {
                peReadout.textContent = pe.value;
                pe.addEventListener(`input`, function() { peReadout.textContent = pe.value; });
            }

            // Bonus slider readout.
            const bo = document.getElementById(`bonusInput`);
            const boReadout = document.getElementById(`bonusReadout`);
            if (bo && boReadout) {
                boReadout.textContent = bo.value;
                bo.addEventListener(`input`, function() { boReadout.textContent = bo.value; });
            }

            // Evaluation weighting live total (must sum to 100%).
            const wIds = [`priceWeightInput`, `qualityWeightInput`];
            const wReadout = document.getElementById(`weightReadout`);
            const recompute = function() {
                let total = 0;
                wIds.forEach((id) => {
                    const el = document.getElementById(id);
                    if (el) total += (parseInt(el.value, 10) || 0);
                });
                if (wReadout) wReadout.textContent = total;
                const bar = document.querySelector(`.publicvaluesim-alloc-readout`);
                if (bar) bar.style.color = (total !== 100) ? `#c0392b` : ``;
            };
            wIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

        _brl(v) {
            // R$ with comma decimal separator, one decimal in millions, e.g. R$21,2M.
            const rounded = Math.round(Number(v) * 10) / 10;
            return `R$` + rounded.toFixed(1).replace(`.`, `,`) + `M`;
        }

        _composite(ds) {
            const valuePV = Math.round(ds.valuePV);
            const quality = Math.round(ds.quality);
            const account = Math.round(ds.account);
            return Math.round(valuePV * 0.40 + quality * 0.30 + account * 0.30);
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        getChartConfig() {
            return {
                publicValueChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: this._cl(`legend_value`, `Public Value`),
                                data: [],
                                borderColor: `#0f7a4f`,
                                backgroundColor: `rgba(15,122,79,0.14)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#0f7a4f`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_quality`, `Service Quality`),
                                data: [],
                                borderColor: `#2f7fb0`,
                                backgroundColor: `rgba(47,127,176,0.10)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2f7fb0`,
                                yAxisID: `y`
                            },
                            {
                                label: this._cl(`legend_account`, `Accountability`),
                                data: [],
                                borderColor: `#6a4fb0`,
                                backgroundColor: `rgba(106,79,176,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#6a4fb0`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#1d2b24`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#5b7064` }, grid: { color: `rgba(15,61,46,0.08)` },
                                title: { display: true, text: this._cl(`axis_score`, `0–100`), color: `#5b7064` }
                            },
                            x: {
                                ticks: { color: `#5b7064` }, grid: { color: `rgba(15,61,46,0.06)` },
                                title: { display: true, text: this._cl(`axis_round`, `Round`), color: `#5b7064` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.valueHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                publicValueChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.valueHistory },
                        { data: ds.qualityHistory },
                        { data: ds.accountHistory }
                    ]
                }
            };
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const valuePV = Math.round(ds.valuePV);
            const quality = Math.round(ds.quality);
            const account = Math.round(ds.account);

            const hitTarget = valuePV >= this.TARGET_VALUE;
            const accountable = account >= 60;
            const qualitySafe = quality >= 60;
            const composite = this._composite(ds);

            let performanceKey = `grade_failure`;
            if (ds.dispensaUsed) performanceKey = `grade_dispensa`;
            else if (hitTarget && accountable && qualitySafe && composite >= 72) performanceKey = `grade_value`;
            else if (hitTarget && accountable && qualitySafe) performanceKey = `grade_agile`;
            else if (hitTarget && !accountable) performanceKey = `grade_indefensible`;
            else if (hitTarget && !qualitySafe) performanceKey = `grade_risky`;
            else if (valuePV > 40) performanceKey = `grade_short`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (ds.dispensaUsed) insights.push(window.mySimulation.t(`insight_dispensa`));
            else if (hitTarget && accountable && qualitySafe) insights.push(window.mySimulation.t(`insight_value`));
            else if (hitTarget && !accountable) insights.push(window.mySimulation.t(`insight_indefensible`));
            else if (hitTarget && !qualitySafe) insights.push(window.mySimulation.t(`insight_risky`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.surgeBreached) insights.push(window.mySimulation.t(`insight_surge`));
            if (quality < 45) insights.push(window.mySimulation.t(`insight_lowquality`));
            if (account < 45) insights.push(window.mySimulation.t(`insight_lowaccount`));
            if (hitTarget && accountable && qualitySafe && account >= 70) insights.push(window.mySimulation.t(`insight_tce`));

            return {
                valuePV: valuePV,
                quality: quality,
                account: account,
                hitTarget: hitTarget,
                composite: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                sound: (hitTarget && accountable && qualitySafe && !ds.dispensaUsed),
                dispensaUsed: ds.dispensaUsed,
                surgeBreached: ds.surgeBreached,
                contractValue: ds.contractValue,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.composite === `number` ? s.composite : 0);
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const metBadge = s.sound
                ? `<span class="publicvaluesim-cm-badge publicvaluesim-cm-yes">` + T(`cm_value`) + `</span>`
                : `<span class="publicvaluesim-cm-badge publicvaluesim-cm-no">` + T(`cm_novalue`) + `</span>`;
            let failBadges = ``;
            if (s.dispensaUsed) failBadges += ` <span class="publicvaluesim-cm-badge publicvaluesim-cm-fail">` + T(`cm_dispensa`) + `</span>`;
            if (s.surgeBreached) failBadges += ` <span class="publicvaluesim-cm-badge publicvaluesim-cm-fail">` + T(`cm_surge`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const contract = `R$` + Number(s.contractValue || 0).toFixed(1) + `M`;
            const metrics = ``
                + `<div class="publicvaluesim-cm-metric"><span class="publicvaluesim-cm-mv">` + Math.round(s.valuePV || 0) + `</span><span class="publicvaluesim-cm-ml">` + T(`cm_m_value`) + `</span></div>`
                + `<div class="publicvaluesim-cm-metric"><span class="publicvaluesim-cm-mv">` + Math.round(s.quality || 0) + `</span><span class="publicvaluesim-cm-ml">` + T(`cm_m_quality`) + `</span></div>`
                + `<div class="publicvaluesim-cm-metric"><span class="publicvaluesim-cm-mv">` + Math.round(s.account || 0) + `</span><span class="publicvaluesim-cm-ml">` + T(`cm_m_account`) + `</span></div>`
                + `<div class="publicvaluesim-cm-metric"><span class="publicvaluesim-cm-mv">` + contract + `</span><span class="publicvaluesim-cm-ml">` + T(`cm_m_contract`) + `</span></div>`;
            return ``
                + `<div class="publicvaluesim-completion">`
                +   `<div class="publicvaluesim-cm-head">`
                +     `<div class="publicvaluesim-cm-score">` + score + `<span class="publicvaluesim-cm-score-max">/100</span></div>`
                +     `<div class="publicvaluesim-cm-grade">` + grade + ` ` + metBadge + failBadges + `</div>`
                +   `</div>`
                +   `<div class="publicvaluesim-cm-metrics">` + metrics + `</div>`
                +   `<div class="publicvaluesim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="publicvaluesim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.dispensaUsed) return window.mySimulation.t(`hint_dispensa`);
            if (ds.surgeBreached) return window.mySimulation.t(`hint_surge`);
            if (ds.quality < 35) return window.mySimulation.t(`hint_quality`);
            if (ds.account < 35) return window.mySimulation.t(`hint_account`);
            if (state.currentPeriod >= 3 && ds.valuePV < 45) return window.mySimulation.t(`hint_behind`);
            if (ds.valuePV >= this.TARGET_VALUE && ds.quality >= 60 && ds.account >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.valuePV`, label: `Public Value`, i18nKey: `col_value`, formatter: (v) => Math.round(v) },
                { key: `results.quality`, label: `Quality`, i18nKey: `col_quality`, formatter: (v) => Math.round(v) },
                { key: `results.account`, label: `Account.`, i18nKey: `col_account`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

        getTranslations() {
            return {
                en: {
                    title:                  `Public Value`,
